from pathlib import Path
import hashlib,json,datetime,zipfile
ROOT=Path(__file__).resolve().parents[1];BASE=ROOT/'artifacts/analog_asic'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def rel(p):return p.relative_to(ROOT).as_posix()
def main():
 old=BASE/'assembly/article_module_catalog_v6.json';cat=json.loads(old.read_text());assert all(sha(ROOT/n)==h for n,h in cat['sha256'].items());paths={old,Path(__file__)};reports={}
 specs=[('gf180_nonoverlap_phase_pair_v2','screen_gf180_nonoverlap_phase_pair_nominal.py','gf180_nonoverlap_phase_pair_nominal_src'),('gf180_two_phase_analog_transfer_v5','screen_gf180_two_phase_analog_transfer_nominal.py','gf180_two_phase_analog_transfer_nominal_src')]
 for i,(cell,script,prefix) in enumerate(specs):
  d=BASE/'layout'/cell;rp=BASE/'results'/(prefix+sha(ROOT/'scripts'/script)[:12]+'.json');r=json.loads(rp.read_text());reports[cell]=r;q=json.loads((d/'qualification.json').read_text());fq=json.loads((d/'flat_cap_qualification.json').read_text());assert r['module_simulation_completed'] and q['magic_drc_count']==q['gds_roundtrip_drc_count']==0 and q['lvs_unique'] and q['gds_roundtrip_lvs_unique'] and fq['flat_lvs_unique'] and not fq['negative_aggregate_branches']
  files=[d/(cell+'.gds'),d/(cell+'.lef'),d/(cell+'_flat_cap.spice'),d/'qualification.json',d/'abstract_qualification.json',d/'flat_cap_qualification.json',rp];paths.update(files)
  entry={'cell':cell,'mos_count':q['mos_count'],'native_mim_count':q['native_mim_count'],'ports':q['ports'],'bbox_um':q['bbox_um'],'module_layout_and_nominal_simulation_artifacts_complete':True,'views':{p.name:rel(p) for p in files},'limitations':r['scope']}
  if i==0:cat['modules'].append({'role':'native_nonoverlap_switch_phase_pair',**entry})
  else:cat['characterization_assemblies'].append({'dense_resident_leaf':False,'complete_neuron_functionally_accepted':False,**entry})
  for p in files:cat['sha256'][rel(p)]=sha(p)
 cat['revision']=7;cat['previous_catalog']=rel(old);cat['next_physical_modules']=['shared_bias_reference','autonomous_event_and_bin_phase_sequence','inhibition_adaptation_and_readout_interfaces','dense_resident_and_weight_cells'];cat['next_assembly']='Use qualified local phase pair to construct bounded event/commit controls; remaining references, adaptation/inhibition/readout, then compact dense tile/full executed hierarchy. Keep charge-sharing interface benchmark distinct from accepted unity-gain reader.'
 cp=BASE/'assembly/article_module_catalog_v7.json';assert not cp.exists();cp.write_text(json.dumps(cat,indent=2)+'\n');paths.add(cp)
 phase=reports[specs[0][0]];transfer=reports[specs[1][0]];audit={'catalog':rel(cp),'module_artifact_sets':len(cat['modules']),'characterization_assemblies':len(cat['characterization_assemblies']),'phase_fanout_cases':phase['cases'],'phase_all_fanouts_nonoverlap':phase['all_fanouts_nonoverlap'],'transfer_cases':transfer['cases'],'transfer_all_cases_primary_nonoverlap':transfer['all_cases_primary_nonoverlap'],'transfer_output_monotonic':transfer['output_monotonic_across_data'],'sampling_metric_interpretation':'held_end_sample_v at2.45us is tracking while sample TG remains ON; tiny sampling_error_v is not released-hold accuracy. Output transfer errors include release injection and passive charge sharing.','scope':'Local native switch-phase support, not autonomous update controller. Logic-threshold gap does not prove zero TG conductance overlap. Native TG/MIM transfer exposes passive charge sharing and clock injection; not a new unity-gain analog reader. External commands/rails/data remain. GDS footprints are characterization macros, not dense storage area.','full_chip_layout_complete':False,'original_float_accuracy_accepted':False,'full_5ms_population_service_accepted':False,'sha256':{rel(p):sha(p) for p in sorted(paths)}}
 ap=BASE/'results/gf180_native_phase_transfer_boundary.json';assert not ap.exists();ap.write_text(json.dumps(audit,indent=2)+'\n')
 docs=[ROOT/'docs'/n for n in ['AGENTS.md','ACTIVE_TASKS.md','ARCHITECTURE.md','DECISIONS.md','RESULTS.md','PROGRESS.md','project_spec.yaml']];stamp=datetime.datetime.now(datetime.timezone.utc).strftime('%Y%m%dT%H%M%SZ');zp=BASE/'documentation_history'/('project_docs_before_native_phase_transfer_'+stamp+'.zip')
 with zipfile.ZipFile(zp,'x',zipfile.ZIP_DEFLATED) as z:
  for p in docs:z.writestr(rel(p),p.read_bytes())
 zp.with_suffix('.json').write_text(json.dumps({'archive_sha256':sha(zp),'files':{rel(p):{'bytes':p.stat().st_size,'sha256':sha(p)} for p in docs}},indent=2)+'\n')
 gaps=[c['minimum_handoff_gap_ns'] for c in phase['cases']];errors=[c['output_final_error_v']*1000 for c in transfer['cases']];gaptext='/'.join(f'{x:.3f}' for x in gaps);errtext='/'.join(f'{x:+.3f}' for x in errors)
 section=f'''\n## Native switch-phase support and analog handoff - 2026-10-10\n\n[Boundary audit](../{rel(ap)}) and [catalog revision7](../{rel(cp)}) add an18MOS native nonoverlap phase module and26MOS/2MIM physical sampling/transfer characterization assembly. Ten reusable module artifact sets and seven characterization assemblies now have checked GDS/DRC/LVS/LEF/flat views and completed nominal simulations. Full-chip layout remains unfinished.\n\nThe interlock derives PHIA=CMD AND NOT PHIB and PHIB=NOT CMD AND NOT PHIA, sensing actual phase outputs through separate native inverters. Extracted48-branch module at1MHz,27C typical, loaded with1/4/16 native inverter inputs on each output has minimum handoff gaps{gaptext}ns and no primary-phase simultaneous logic-high interval. Primary output transients range about-0.166 to3.316V; no PVT/reliability qualification is claimed. These are threshold-crossing measurements, not zero-conductance TG guarantees.\n\nThe physical assembly adds DATA-to-HOLD and HOLD-to-OUTPUT native TGs, two minimumMIM plates, and reset TG/inverter. Its81-branch flat extraction includes all intermodule wiring. Three DATA values1.4/1.65/1.9V produce final errors{errtext}mV after six passive transfers. Output monotonic across DATA:{transfer['output_monotonic_across_data']}; primary phases remain nonoverlapping:{transfer['all_cases_primary_nonoverlap']}. Each transfer intentionally shares charge with the output plate, and switching offsets are retained. The near-zero reported sampling_error_v is measured while the sample TG is still ON; it proves tracking only, not released-hold accuracy. This benchmark is not an accepted unity-gain reader or model state-copy path.\n\nEarlier placement/escape failures are preserved. Clearances must cover routing escape envelopes as well as child bounding boxes. MinimumMIM P/M/VSS uses the previously qualified pin-specific escape pattern; generic top-metal lifts can intersect cap geometry. No DRC rule was relaxed. External command/reset/data and supply remain; autonomous event/bin sequencing, shared references, adaptation/inhibition/readout and dense/full assembly are still required.\n'''
 p=ROOT/'docs/RESULTS.md';s=p.read_text();i=s.index('\n## ');p.write_text(s[:i]+section+s[i:])
 p=ROOT/'docs/ACTIVE_TASKS.md';s=p.read_text().replace('Nine reusable GF180','Ten reusable GF180').replace('Six routed characterization assemblies','Seven routed characterization assemblies').replace('Nine module artifact sets and six routed characterization assemblies','Ten module artifact sets and seven routed characterization assemblies').replace('Nine reusable physical modules and six characterization assemblies','Ten reusable physical modules and seven characterization assemblies').replace('catalog revision6','catalog revision7').replace('article_module_catalog_v6.json','article_module_catalog_v7.json').replace('contains nine completed module view/simulation sets and six characterization assemblies','contains ten completed module view/simulation sets and seven characterization assemblies');a=s.index('| Job status |');b=s.index('\n',a);s=s[:a]+'| Job status | Native phase pair and TG/MIM transfer assembly nominal simulations completed; no live simulator |'+s[b:];s=s.replace('3. Complete shared references/phase sequencing, adaptation, inhibition and final readout interfaces.','3. Native phase interlock and physical TG/MIM transfer benchmark now complete. Continue autonomous event/bin phase sequencing, shared references, adaptation, inhibition and final readout interfaces.');s=s.replace('RESULTS.md#physically-joined-weighted-signed-charge-path---2026-10-10','RESULTS.md#native-switch-phase-support-and-analog-handoff---2026-10-10');p.write_text(s)
 p=ROOT/'docs/PROGRESS.md';s=p.read_text();i=s.index('\n## Milestones');s=s[:i]+f'\nNative phase-support milestone:18MOS interlock and26MOS/2MIM physical handoff assembly complete nominal extracted simulations and physical views. Minimum fanout1/4/16 gaps{gaptext}ns; passive transfer final errors{errtext}mV. Catalog revision7: ten modules/seven characterization assemblies; not full layout or autonomous controller. Pre-update exact docs: `{rel(zp)}`.\n'+s[i:];p.write_text(s)
 p=ROOT/'docs/ARCHITECTURE.md';s=p.read_text().replace('Catalog revision6 owns current','Catalog revision7 owns current');i=s.index('\n## ');s=s[:i]+'\n## Native local phase interlock\n\nTwo cross-interlocked native AND paths generate opposite phases from external CMD, with separate inverters sensing actual primary outputs. PHIA=CMD AND NOT PHIB; PHIB=NOT CMD AND NOT PHIA. The complements drive TG PMOS gates. This local switch-timing circuit does not implement bin completion, event requests, commit order, adaptation age or autonomous sequencing. A routed TG/MIM sample-transfer assembly records physical charge sharing and switching offsets; it is not a replacement for the qualified isolated analog reader.\n'+s[i:];p.write_text(s)
 p=ROOT/'docs/DECISIONS.md';s=p.read_text();i=s.index('\n## ');s=s[:i]+'\n## Use actual-output interlock for local analog phases - 2026-10-10\n\nRetain the native18MOS cross-interlock after three nominal native fanout cases show primary-phase logic nonoverlap. Feed back actual outputs through separate inverters; NAND precursor complements can release the opposite branch before the primary output falls. Keep local switch timing separate from autonomous event/bin control. Preserve TG/MIM passive charge-sharing measurements without calling them unity-gain state transfer. Physical placement must reserve pin-escape envelopes; use the qualified minimumMIM pin-specific route pattern.\n'+s[i:];p.write_text(s)
 p=ROOT/'docs/project_spec.yaml';raw=p.read_bytes();h,t=raw.split(b'\ndocument:',1);s=h.decode().replace('article_module_catalog_v6.json','article_module_catalog_v7.json').replace('gf180_signed_weight_charge_boundary.json','gf180_native_phase_transfer_boundary.json').replace('  live_sessions: [two_phase_analog_transfer_nominal_bounded_120s]','  live_sessions: []').replace('status: nine_modules_six_assemblies_guarded_duration_signed_charge_nominal_complete','status: ten_modules_seven_assemblies_native_phase_transfer_nominal_complete').replace('next_action: remaining_bias_phase_adaptation_inhibition_readout_functions_dense_tile_full_assembly','next_action: autonomous_event_bin_controls_shared_references_adaptation_inhibition_readout_dense_full_assembly');p.write_bytes(s.encode()+b'\ndocument:'+t)
 print(json.dumps({'catalog':rel(cp),'audit':rel(ap),'minimum_gaps_ns':gaps,'transfer_final_errors_mv':errors,'transfer_primary_nonoverlap':transfer['all_cases_primary_nonoverlap']},indent=2))
